"""AI-generated by ChatGPT: replay the retained 14 scripts against this checkout."""
import hashlib
import json
from pathlib import Path
import platform
import shlex
import subprocess
import sys
import tempfile
import zipfile

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent / 'raw'
ARCHIVE = ROOT / 'review/round2_chatgpt/SML_ROUND2_TEST_REVIEW_EVIDENCE_2026-10-30.zip'


def main():
    OUT.mkdir(exist_ok=True)
    results = []
    with tempfile.TemporaryDirectory(prefix='sml-replay-') as tmp:
        with zipfile.ZipFile(ARCHIVE) as z:
            for name in z.namelist():
                if not (Path(tmp) / name).resolve().is_relative_to(Path(tmp).resolve()):
                    raise ValueError('unsafe archive path')
            z.extractall(tmp)
        src = Path(tmp) / 'sml_round2_review'
        manifest = subprocess.run(['sha256sum', '-c', 'MANIFEST_REVIEW.sha256'], cwd=src,
                                  text=True, capture_output=True)
        (OUT / 'manifest.stdout.txt').write_text(manifest.stdout)
        (OUT / 'manifest.stderr.txt').write_text(manifest.stderr)
        print(f'ARCHIVE_MANIFEST exit={manifest.returncode}')
        if manifest.returncode:
            return 2
        scripts = sorted((src / 'scripts').glob('test_*.py'))
        assert len(scripts) == 14, len(scripts)
        for script in scripts:
            cmd = [sys.executable, str(script), '--target', str(ROOT)]
            p = subprocess.run(cmd, cwd=src, text=True, capture_output=True, timeout=120)
            (OUT / (script.stem + '.stdout.txt')).write_text(p.stdout)
            (OUT / (script.stem + '.stderr.txt')).write_text(p.stderr)
            (OUT / (script.stem + '.command.txt')).write_text(
                'cd ' + shlex.quote(str(src)) + '\n' + shlex.join(cmd) + '\n')
            results.append({'script': script.name, 'exit': p.returncode,
                            'script_sha256': hashlib.sha256(script.read_bytes()).hexdigest(),
                            'command': cmd, 'cwd': str(src)})
            print(f'{script.name}: {"PASS" if p.returncode == 0 else "FAIL"} exit={p.returncode}', flush=True)
    (OUT / 'results.json').write_text(json.dumps({
        'python': sys.version, 'platform': platform.platform(),
        'source_memory_sha256': hashlib.sha256((ROOT / 'sml/memory.py').read_bytes()).hexdigest(),
        'archive_sha256': hashlib.sha256(ARCHIVE.read_bytes()).hexdigest(),
        'results': results}, indent=2) + '\n')
    passed = sum(r['exit'] == 0 for r in results)
    print(f'TOTAL {passed}/14 scripts exit 0')
    return 0 if passed == 14 else 1


if __name__ == '__main__':
    raise SystemExit(main())
